import re
import json

def parse_books_json(filepath):
    with open(filepath, 'r') as f:
        text = f.read()

    books = []
    lines = text.split('\n')
    current_book = {}

    for line in lines:
        line_stripped = line.strip()
        if not line_stripped:
            continue

        if '"title":' in line_stripped or "'title':" in line_stripped:
            # Save previous book if exists
            if current_book:
                books.append(current_book)
                current_book = {}
            # Extract title
            match = re.search(r'["\']title["\']:\s*["\']?([^"\'}]+)["\']?', line_stripped)
            if match:
                current_book['title'] = match.group(1).strip('"\'')
        elif '"author":' in line_stripped or "'author':" in line_stripped:
            match = re.search(r'["\']author["\']:\s*["\']?([^"\'}]+)["\']?', line_stripped)
            if match:
                current_book['author'] = match.group(1).strip('"\'')
        elif '"year":' in line_stripped or "'year':" in line_stripped:
            match = re.search(r'["\']year["\']:\s*([^,\}\]]+)', line_stripped)
            if match:
                val = match.group(1).strip().strip('"\'')
                try:
                    current_book['year'] = int(val)
                except:
                    current_book['year'] = val
        elif '"genre":' in line_stripped or "'genre':" in line_stripped:
            match = re.search(r'["\']genre["\']:\s*["\']?([^"\'}]+)["\']?', line_stripped)
            if match:
                current_book['genre'] = match.group(1).strip('"\'')
        elif '"pages":' in line_stripped or "'pages':" in line_stripped:
            match = re.search(r'["\']pages["\']:\s*([0-9]+)', line_stripped)
            if match:
                current_book['pages'] = int(match.group(1))

    # Don't forget the last book
    if current_book:
        books.append(current_book)

    return books

def parse_prices_json(filepath):
    with open(filepath, 'r') as f:
        text = f.read()

    prices = []
    lines = text.split('\n')
    current_price = {}

    for line in lines:
        line_stripped = line.strip()
        if not line_stripped:
            continue

        if '"title":' in line_stripped or "'title':" in line_stripped:
            if current_price:
                prices.append(current_price)
                current_price = {}
            match = re.search(r'["\']title["\']:\s*["\']?([^"\'}]+)["\']?', line_stripped)
            if match:
                current_price['title'] = match.group(1).strip('"\'')
        elif '"price":' in line_stripped or "'price':" in line_stripped:
            match = re.search(r'["\']price["\']:\s*([0-9.]+)', line_stripped)
            if match:
                current_price['price'] = float(match.group(1))

    if current_price:
        prices.append(current_price)

    return prices

books = parse_books_json('/workdir/data/books.json')
prices = parse_prices_json('/workdir/data/book_prices.json')

print("Books parsed:", len(books))
print("Prices parsed:", len(prices))
print("Sample book:", books[0])
print("Sample price:", prices[0])
