    prices = [b['price'] for b in books_list]
    total_price = sum(prices)
    if not (115 <= total_price <= 120):
        continue
    if max(prices) > 25 or min(prices) < 5:  # Individual constraints already checked but let's verify
        continue  # Actually min >= 5 is checked by individual filter
    if max(prices) < 15:  # Most expensive must be >= 15
        continue
    if max(prices) - min(prices) >= 12:  # variance < 12 means max-min < 12
        continue

    # Temporal constraints
    years = [b['year'] for b in books_list]
    after_1990 = sum(1 for y in years if y > 1990)
    between = sum(1 for y in years if 1960 <= y <= 1990)
    before = sum(1 for y in years if y < 1960)
    if after_1990 != 3 or between != 3 or before != 2:
        continue

    # Decade constraints
    decades = [(b['year'] // 10) * 10 for b in books_list]
    unique_decades = len(set(decades))
    if unique_decades < 6:
        continue
    decade_counts = Counter(decades)
    if any(c > 2 for c in decade_counts.values()):
        continue

    # Diversity constraints - authors
    authors = [b['author'] for b in books_list]
    if len(set(authors)) != 8:
        continue

    # Genres
    genres = [b['genre'] for b in books_list]
    genre_counts = Counter(genres)
    if any(c > 2 for c in genre_counts.values()):
        continue
    if len(set(genres)) < 5:
        continue

    # Horror exactly 1
    horror_count = sum(1 for b in books_list if b['genre'] == 'Horror')
    if horror_count != 1:
        continue

    # At least 2 books with numbers in title
    num_count = sum(1 for b in books_list if has_number(b['title']))
    if num_count < 2:
        continue

    # Page constraints
    pages = [b['pages'] for b in books_list]
    total_pages = sum(pages)
    if not (2800 <= total_pages <= 3600):
        continue
    if sum(1 for p in pages if p > 400) < 3:
        continue
